steps.run:
set -euo pipefail
response_file="$(mktemp)"
status="$(curl --silent --show-error --retry 4 --retry-delay 3 --retry-all-errors \
  -o "$response_file" \
  -w '%{http_code}' \
  -X POST \
  -H "Authorization: Bearer $OIDC_TOKEN" \
  -H "x-vercel-trusted-oidc-idp-token: $VERCEL_TRUSTED_OIDC_TOKEN" \
  "$DEPLOYMENT_URL/api/internal/product-query-protection-shadow")"

node - "$response_file" "$GITHUB_SHA" "$status" <<'NODE'
const fs = require("fs");
const [file, expectedSha, httpStatus] = process.argv.slice(2);
const payload = JSON.parse(fs.readFileSync(file, "utf8"));
const safe = {
  result: payload.result || null,
  deploymentSha: payload.deploymentSha || null,
  deploymentRef: payload.deploymentRef || null,
  contractVersion: payload.contractVersion || null,
  sunscreenCorpusCount: payload.sunscreenCorpusCount ?? null,
  authorityResolvedCount: payload.authorityResolvedCount ?? null,
  credentialMode: payload.credentialMode || null,
  authorityFailureCounts: payload.authorityFailureCounts || null,
  auditDecision: payload.audit?.overallDecision || null,
  readyAxes: payload.audit?.readyAxes || null,
  enabledAxes: payload.enabledAxes || null,
  scenarioCount: payload.scenarioCount ?? null,
  allScenarioChecksPass: payload.allScenarioChecksPass ?? null,
  scenarios: Array.isArray(payload.scenarios)
    ? payload.scenarios.map((item) => ({
        id: item.id,
        baselineStatus: item.baselineStatus,
        shadowStatus: item.shadowStatus,
        top5OverlapCount: item.top5OverlapCount,
        orderChanged: item.orderChanged,
        changedProductCount: item.changedProductCount,
        maxRankShift: item.maxRankShift,
        appliedProtectionProductCount: item.appliedProtectionProductCount,
        maxAppliedProtectionDelta: item.maxAppliedProtectionDelta,
        enabledAxes: item.enabledAxes,
        pass: item.pass,
        failures: item.failures
      }))
    : null,
  limits: payload.limits || null,
  secretValueExposed: payload.secretValueExposed ?? null,
  queryTextExposed: payload.queryTextExposed ?? null
};
console.log(`DATA_AI29C_B_RUNTIME_EVIDENCE=${JSON.stringify(safe)}`);

if (httpStatus !== "200") process.exit(1);
if (payload.deploymentSha !== expectedSha || payload.deploymentRef !== "main") process.exit(2);
if (payload.result !== "PASS") process.exit(3);
if (payload.contractVersion !== "product-query-protection-shadow-v1") process.exit(4);
if (!Number.isInteger(payload.sunscreenCorpusCount) || payload.sunscreenCorpusCount < 1) process.exit(5);
if (payload.authorityResolvedCount !== payload.sunscreenCorpusCount) process.exit(6);
if (!["dedicated", "admission_shadow_fallback"].includes(payload.credentialMode)) process.exit(23);
const failureCounts = payload.authorityFailureCounts || {};
const allowedFailureKeys = [
  "credential_unavailable",
  "read_timeout",
  "read_failed",
  "malformed_or_stale_authority",
  "authority_unavailable_other"
];
if (Object.keys(failureCounts).sort().join(",") !== allowedFailureKeys.sort().join(",")) process.exit(24);
if (allowedFailureKeys.some((key) => failureCounts[key] !== 0)) process.exit(25);
if (payload.audit?.overallDecision !== "HOLD_NO_DISCRIMINATING_AXIS") process.exit(7);
if (!Array.isArray(payload.audit?.readyAxes) || payload.audit.readyAxes.length !== 0) process.exit(8);
if (!Array.isArray(payload.enabledAxes) || payload.enabledAxes.length !== 0) process.exit(9);
if (payload.scenarioCount !== 4 || payload.allScenarioChecksPass !== true) process.exit(10);
if (!Array.isArray(payload.scenarios) || payload.scenarios.length !== 4) process.exit(11);
if (payload.scenarios.some((item) => item?.pass !== true)) process.exit(12);
if (payload.scenarios.some((item) => item?.orderChanged !== false)) process.exit(13);
if (payload.scenarios.some((item) => item?.appliedProtectionProductCount !== 0)) process.exit(14);
if (payload.scenarios.some((item) => item?.maxAppliedProtectionDelta !== 0)) process.exit(15);
const failClosed = payload.scenarios.find((item) => item?.id === "outdoor_only_fail_closed");
if (failClosed?.baselineStatus !== "insufficient_supported_intent") process.exit(16);
if (failClosed?.shadowStatus !== "insufficient_supported_intent") process.exit(17);
if (payload.limits?.productionRankingChanged !== false) process.exit(18);
if (payload.limits?.productionCutoverAuthorized !== false) process.exit(19);
if (payload.limits?.outdoorRankableSignalAuthorized !== false) process.exit(20);
if (payload.limits?.persistence !== false || payload.limits?.publicActivation !== false) process.exit(21);
if (payload.secretValueExposed !== false || payload.queryTextExposed !== false) process.exit(22);
NODE

rm -f "$response_file"

