  recommendationLogWrite: payload.recommendationLogWrite ?? null,
  publicActivation: payload.publicActivation ?? null,
  scenarios: Array.isArray(payload.scenarios)
    ? payload.scenarios.map((item) => ({
        id: item.id,
        status: item.status,
        effectiveCategory: item.effectiveCategory,
        candidateCount: item.candidateCount,
        resultCount: item.resultCount,
        constraintStatus: item.constraintStatus,
        parity: item.parity,
        pass: item.pass,
        failures: item.failures
      }))
    : null
};
console.log(`DATA_AI3_RUNTIME_EVIDENCE=${JSON.stringify(safe)}`);
if (httpStatus !== "200") process.exit(1);
if (payload.deploymentSha !== expectedSha || payload.deploymentRef !== "main") process.exit(2);
if (payload.result !== "PASS") process.exit(3);
if (payload.contractVersion !== "product-query-shadow-v1") process.exit(4);
if (!Number.isInteger(payload.candidateCorpusCount) || payload.candidateCorpusCount < 1) process.exit(5);
if (payload.scenarioCount !== 4) process.exit(6);
if (payload.allParity !== true || payload.allScenarioChecksPass !== true) process.exit(7);
if (payload.secretValueExposed !== false || payload.queryTextExposed !== false) process.exit(8);
if (payload.productionWrite !== false || payload.recommendationLogWrite !== false) process.exit(9);
if (payload.publicActivation !== false) process.exit(10);
if (!Array.isArray(payload.scenarios) || payload.scenarios.length !== 4) process.exit(11);
if (payload.scenarios.some((item) => item?.parity !== true || item?.pass !== true)) process.exit(12);
const categoryOnly = payload.scenarios.find((item) => item?.id === "category_only_fail_closed");
if (categoryOnly?.status !== "insufficient_supported_intent" || categoryOnly?.resultCount !== 0) process.exit(13);
const unresolved = payload.scenarios.find((item) => item?.id === "unresolved_constraint_preserved");
if (unresolved?.constraintStatus !== "partial" || !unresolved?.unresolvedTerms?.includes("pregnancy-safe")) process.exit(14);
